/* main.c
 * Demo entry point for StaTable-generated state machine.
 *
 * Target: STM32F405 (QEMU netduinoplus2 / real HW).
 * UART2 outputs status to `-serial stdio` (QEMU) or 115200 8N1.
 *
 * Generated by StaTable Eclipse Installer v0.1.0
 *
 * How to customize
 * ----------------
 * `app_init()` and `app_step()` are weak; provide your own
 * implementations in a separate file to override. By default they
 * print a periodic heartbeat so the demo runs out of the box.
 */
#include <stdint.h>
#include <stdio.h>

/* Provided by syscalls.c */
extern void uart2_init(void);

/* Weak hooks: override in your own .c if desired */
__attribute__((weak)) void app_init(void)
{
    printf("[app_init] StaTable demo starting\n");
}

__attribute__((weak)) void app_step(uint32_t tick)
{
    /* Heartbeat every ~1M iterations (adjust for your clock). */
    if ((tick & 0xFFFFF) == 0) {
        printf("[tick] %lu\n", (unsigned long)tick);
    }
}

/* Simple busy-wait delay */
static void delay(volatile uint32_t n)
{
    while (n--) { __asm__ volatile ("nop"); }
}

int main(void)
{
    uart2_init();

    printf("\n");
    printf("========================================\n");
    printf(" StaTable @@PROJECT_NAME@@ demo\n");
    printf(" Version: @@VERSION@@\n");
    printf(" Target:  STM32F405 (Cortex-M4)\n");
    printf("========================================\n");
    printf("\n");

    app_init();

    uint32_t tick = 0;
    for (;;) {
        app_step(tick);
        tick++;
        delay(1000);
    }
    return 0;
}
